{"path": "frontend/src/components/Dashboard.tsx", "content": "import React, { useEffect, useState, useContext } from 'react';
import { getDashboard } from '../api';
import { AuthContext } from '../App';

export const Dashboard: React.FC = () => {
  const { token } = useContext(AuthContext);
  const [summary, setSummary] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (token) {
      getDashboard(token)
        .then(data => setSummary(data))
        .catch(() => alert('Failed to load dashboard'))
        .finally(() => setLoading(false));
    }
  }, [token]);

  if (loading) return <div className="card"><p>Loading summary...</p></div>;
  if (!summary) return <div className="card"><p>No data yet. Add a receipt or mileage to get started.</p></div>;

  return (
    <div className="card">
      <h2>Dashboard</h2>
      <p>Total Expenses: ${summary.total_expenses.toFixed(2)}</p>
      <p>Mileage Deduction: ${summary.total_mileage_deduction.toFixed(2)}</p>
    </div>
  );
};
"}

{"path": "frontend/src/components/ReceiptUpload.tsx", "content": "import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { uploadReceipt } from '../api';
import { AuthContext } from '../App';

export const ReceiptUpload: React.FC = () => {
  const { token } = useContext(AuthContext);
  const navigate = useNavigate();
  const [file, setFile] = useState<File | null>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [vendor, setVendor] = useState('');
  const [category, setCategory] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) { alert('File required'); return; }
    const formData = new FormData();
    formData.append('file', file);
    formData.append('amount', amount);
    formData.append('date', date);
    formData.append('vendor', vendor);
    formData.append('category', category);
    const res = await uploadReceipt(formData, token!);
    if (res.id) {
      alert('Receipt added successfully!');
      navigate('/dashboard');
    } else {
      alert('Upload failed');
    }
  };

  return (
    <div className="card">
      <h1>Add Receipt</h1>
      <form onSubmit={handleSubmit}>
        <label htmlFor="file">Image</label>
        <input id="file" type="file" accept="image/*" onChange={e => setFile(e.target.files?.[0] || null)} required />
        <label htmlFor="amount">Amount (USD)</label>
        <input id="amount" type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} required />
        <label htmlFor="date">Date</label>
        <input id="date" type="date" value={date} onChange={e => setDate(e.target.value)} required />
        <label htmlFor="vendor">Vendor</label>
        <input id="vendor" type="text" value={vendor} onChange={e => setVendor(e.target.value)} required />
        <label htmlFor="category">Category</label>
        <input id="category" type="text" value={category} onChange={e => setCategory(e.target.value)} required />
        <button type="submit" className="primary">Upload receipt</button>
      </form>
    </div>
  );
};
"}

