{"path": "backend/app/routers/auth.py", "content": """"Authentication routes: register and login."""
from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from .. import models, schemas, auth, database

router = APIRouter(prefix="/auth", tags=["auth"])

@router.post("/register", response_model=schemas.Token, status_code=201)
def register(user: schemas.UserCreate, db: Session = Depends(database.get_db)):
    existing = db.query(models.User).filter(models.User.email == user.email).first()
    if existing:
        raise HTTPException(status_code=400, detail="Email already registered")
    hashed = auth.get_password_hash(user.password)
    db_user = models.User(email=user.email, hashed_password=hashed)
    db.add(db_user)
    db.commit()
    db.refresh(db_user)
    # Create JWT token for auto-login
    access_token = auth.create_access_token(data={"sub": db_user.id})
    return {"access_token": access_token, "token_type": "bearer"}

@router.post("/login", response_model=schemas.Token)
def login(form: schemas.UserLogin, db: Session = Depends(database.get_db)):
    user = db.query(models.User).filter(models.User.email == form.email).first()
    if not user or not auth.verify_password(form.password, user.hashed_password):
        raise HTTPException(status_code=401, detail="Incorrect email or password")
    access_token = auth.create_access_token(data={"sub": user.id})
    return {"access_token": access_token, "token_type": "bearer"}
"}

{"path": "frontend/src/api.ts", "content": "// Simple API wrapper using fetch. Provides functions for backend endpoints.

function getHeaders(token?: string): HeadersInit {
  const headers: HeadersInit = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;
  return headers;
}

export async function register(email: string, password: string) {
  const res = await fetch('/auth/register', {
    method: 'POST',
    headers: getHeaders(),
    body: JSON.stringify({ email, password }),
  });
  return res.json();
}

export async function login(email: string, password: string) {
  const res = await fetch('/auth/login', {
    method: 'POST',
    headers: getHeaders(),
    body: JSON.stringify({ email, password }),
  });
  return res.json();
}

export async function uploadReceipt(data: FormData, token: string) {
  const res = await fetch('/receipts', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: data,
  });
  return res.json();
}

export async function getDashboard(token: string) {
  const res = await fetch('/dashboard/summary', {
    headers: getHeaders(token),
  });
  if (!res.ok) {
    // Throw to be caught by caller
    const err = await res.json();
    throw new Error(err.detail || 'Failed to load dashboard');
  }
  return res.json();
}

export async function exportPdf(token: string) {
  const res = await fetch('/export/pdf', { headers: getHeaders(token) });
  if (!res.ok) throw new Error('Export PDF failed');
  return res.blob();
}

export async function exportCsv(token: string) {
  const res = await fetch('/export/csv', { headers: getHeaders(token) });
  if (!res.ok) throw new Error('Export CSV failed');
  return res.blob();
}
"}

{"path": "frontend/src/components/Register.tsx", "content": "import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { register } from '../api';
import { AuthContext } from '../App';

export const Register: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const { setToken } = useContext(AuthContext);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password !== confirm) {
      setError('Passwords do not match');
      return;
    }
    // Register the user (backend now returns JWT token)
    const res = await register(email, password);
    if (res.access_token) {
      setToken(res.access_token);
      navigate('/dashboard');
    } else {
      setError(res.detail || 'Registration failed');
    }
  };

  return (
    <div className="card">
      <h1>Create your account</h1>
      {error && <p className="error" role="alert">{error}</p>}
      <form onSubmit={handleSubmit}>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          autoComplete="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          required
        />
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          autoComplete="new-password"
          value={password}
          onChange={e => setPassword(e.target.value)}
          required
        />
        <label htmlFor="confirm">Confirm password</label>
        <input
          id="confirm"
          type="password"
          autoComplete="new-password"
          value={confirm}
          onChange={e => setConfirm(e.target.value)}
          required
        />
        <button type="submit" className="primary">Create account</button>
      </form>
    </div>
  );
};
"}

{"path": "frontend/src/components/ReceiptUpload.tsx", "content": "import React, { useState, useContext, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { uploadReceipt } from '../api';
import { AuthContext } from '../App';

export const ReceiptUpload: React.FC = () => {
  const { token } = useContext(AuthContext);
  const navigate = useNavigate();
  const [file, setFile] = useState<File | null>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [vendor, setVendor] = useState('');
  const [category, setCategory] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFile(e.target.files?.[0] || null);
  };

  const openFileChooser = () => {
    fileInputRef.current?.click();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) { alert('File required'); return; }
    const formData = new FormData();
    formData.append('file', file);
    formData.append('amount', amount);
    formData.append('date', date);
    formData.append('vendor', vendor);
    formData.append('category', category);
    const res = await uploadReceipt(formData, token!);
    if (res.id) {
      alert('Receipt added successfully!');
      navigate('/dashboard');
    } else {
      alert('Upload failed');
    }
  };

  return (
    <div className="card">
      <h1>Add Receipt</h1>
      <form onSubmit={handleSubmit}>
        <label htmlFor="file">Image</label>
        <input
          id="file"
          type="file"
          accept="image/jpeg,image/png,application/pdf"
          style={{ display: 'none' }}
          ref={fileInputRef}
          onChange={handleFileChange}
          required
        />
        <button type="button" className="secondary" onClick={openFileChooser}>Take photo</button>
        {file && <p>{file.name}</p>}
        <p className="help-text">Supported formats: JPG, PNG, PDF. Max size 5 MB.</p>
        <label htmlFor="amount">Amount (USD)</label>
        <input id="amount" type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} required />
        <label htmlFor="date">Date</label>
        <input id="date" type="date" value={date} onChange={e => setDate(e.target.value)} required />
        <label htmlFor="vendor">Vendor</label>
        <input id="vendor" type="text" value={vendor} onChange={e => setVendor(e.target.value)} required />
        <label htmlFor="category">Category</label>
        <input id="category" type="text" value={category} onChange={e => setCategory(e.target.value)} required />
        <button type="submit" className="primary">Upload receipt</button>
      </form>
    </div>
  );
};
"}

