{"path": "frontend/src/App.tsx", "content": "import React, { createContext, useState, useEffect, ReactNode } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { Login } from './components/Login';
import { Register } from './components/Register';
import { Dashboard } from './components/Dashboard';
import { ReceiptUpload } from './components/ReceiptUpload';
import { MileageForm } from './components/MileageForm';
import { ExportButtons } from './components/ExportButtons';
import { Layout } from './components/Layout';

interface AuthContextProps {
  token: string | null;
  setToken: (token: string | null) => void;
}
export const AuthContext = createContext<AuthContextProps>({ token: null, setToken: () => {} });

const RequireAuth: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { token } = React.useContext(AuthContext);
  return token ? <>{children}</> : <Navigate to="/login" replace />;
};

function App() {
  const [token, setTokenState] = useState<string | null>(null);

  // Load token from localStorage on mount
  useEffect(() => {
    const stored = localStorage.getItem('token');
    if (stored) setTokenState(stored);
  }, []);

  // Persist token changes
  const setToken = (t: string | null) => {
    if (t) {
      localStorage.setItem('token', t);
    } else {
      localStorage.removeItem('token');
    }
    setTokenState(t);
  };

  return (
    <AuthContext.Provider value={{ token, setToken }}>
      <Routes>
        <Route path="/" element={<Register />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        {/* Authenticated routes wrapped with Layout for persistent navigation */}
        <Route
          path="/dashboard"
          element={
            <RequireAuth>
              <Layout>
                <Dashboard />
              </Layout>
            </RequireAuth>
          }
        />
        <Route
          path="/receipt-upload"
          element={
            <RequireAuth>
              <Layout>
                <ReceiptUpload />
              </Layout>
            </RequireAuth>
          }
        />
        <Route
          path="/mileage-form"
          element={
            <RequireAuth>
              <Layout>
                <MileageForm />
              </Layout>
            </RequireAuth>
          }
        />
        <Route
          path="/export"
          element={
            <RequireAuth>
              <Layout>
                <ExportButtons />
              </Layout>
            </RequireAuth>
          }
        />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </AuthContext.Provider>
  );
}

export default App;
"}

{"path":"frontend/src/components/Dashboard.tsx","content":"import React, { useEffect, useState, useContext } from 'react';
import { getDashboard } from '../api';
import { AuthContext } from '../App';

export const Dashboard: React.FC = () => {
  const { token: ctxToken } = useContext(AuthContext);
  const token = ctxToken || localStorage.getItem('token');
  const [summary, setSummary] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    if (token) {
      getDashboard(token)
        .then(data => setSummary(data))
        .catch(err => setError(err.message))
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, [token]);

  if (loading) return <div className="card"><p>Loading summary...</p></div>;
  if (error) return <div className="card"><p className="error" role="alert">Failed to load data. Retry.</p></div>;
